<?php
declare(strict_types=1);
namespace EPejabat\Core;
final class Notifications {
    public static function inApp(\PDO $p,int $user,string $title,string $body,string $module='core'):void {Core::module($p,$module,false);Database::query($p,'INSERT INTO notifications(user_id,title,body,module_code) VALUES(?,?,?,?)',[$user,Core::text($title),Core::text($body,3000),$module]);}
    public static function enqueue(\PDO $p,string $email,string $template,array $payload):int {$email=Core::email($email);if(!in_array($template,['activation','reset','correction'],true)&&RegistrationMaster::profileReady($p)){$preferred=Database::query($p,"SELECT c.email FROM staff_email_contacts c JOIN users u ON u.staff_identity_id=c.staff_identity_id WHERE u.email=? AND c.status='APPROVED' AND c.verified_at IS NOT NULL AND c.is_notification_primary=1 AND u.is_active=1",[$email])->fetchColumn();if($preferred)$email=Core::email($preferred);}if(!Database::query($p,'SELECT 1 FROM notification_templates WHERE template_key=? AND is_active=1',[$template])->fetchColumn())throw new \RuntimeException('Template tidak aktif.');Database::query($p,'INSERT INTO notification_deliveries(email,template_key,payload_cipher) VALUES(?,?,?)',[$email,$template,Crypto::seal(json_encode($payload,JSON_THROW_ON_ERROR))]);return (int)$p->lastInsertId();}
    public static function config(): ?array {$f=APP_ROOT.'/config/smtp.php';if(!is_file($f))return null;$c=require $f;if(!is_array($c))return null;foreach(['host','port','encryption','from_email'] as $k)if(!isset($c[$k])||$c[$k]==='')return null;return $c;}
    public static function process(\PDO $p,int $limit=20):array {return self::run($p,$limit,null,null);}
    public static function processOne(\PDO $p,int $actor,int $id,string $recipient):array {if(!Authorization::super($p,$actor))throw new \RuntimeException("Super Admin diperlukan.");$recipient=Core::email($recipient);if($id<1)throw new \InvalidArgumentException("Delivery ID tidak sah.");$row=Database::query($p,"SELECT email,status FROM notification_deliveries WHERE id=?",[$id])->fetch();if(!$row||$row["status"]!=="QUEUED"||strcasecmp($row["email"],$recipient)!==0)throw new \RuntimeException("Delivery ID/penerima/status tidak sepadan.");$result=self::run($p,1,$id,$recipient);Audit::record($p,"notification.single_retry",$actor,null,(string)$id,"core","Explicit delivery and recipient confirmation",null,$result);return $result;}
    private static function run(\PDO $p,int $limit,?int $id,?string $recipient):array {
        if(!self::config())return ['sent'=>0,'failed'=>0,'blocked'=>true];$result=['sent'=>0,'failed'=>0,'blocked'=>false];
        if((int)Database::query($p,"SELECT GET_LOCK(CONCAT('ep_mail_',LEFT(SHA2(DATABASE(),256),40)),1)")->fetchColumn()!==1)return $result;
        try {$rows=Database::query($p,"SELECT d.*,t.subject,t.body FROM notification_deliveries d JOIN notification_templates t ON t.template_key=d.template_key WHERE d.status='QUEUED' AND d.next_attempt_at<=UTC_TIMESTAMP()".($id!==null?" AND d.id=? AND d.email=?":"")." ORDER BY d.id LIMIT ".max(1,min($limit,100)), $id!==null?[$id,$recipient]:[])->fetchAll();foreach($rows as $r){try{$data=json_decode(Crypto::open($r['payload_cipher']),true,512,JSON_THROW_ON_ERROR);if(isset($data['expires_at'])&&strtotime($data['expires_at'].' UTC')<time())throw new \RuntimeException('Expired delivery');$body=$r['body'];foreach($data as $k=>$v)if(is_scalar($v))$body=str_replace('{{'.$k.'}}',(string)$v,$body);$subject=$r['subject'];if($r['template_key']==='activation'&&($data['context']??null)==='profile_email_contact'){$subject=($data['email_type']??null)==='official'?'Sahkan E-mel Rasmi Tambahan':'Sahkan E-mel Alternatif Tambahan';$body="Ini pengesahan pemilikan e-mel tambahan untuk akaun yang sudah wujud, bukan pengaktifan akaun staf baharu.\n\nLog masuk menggunakan e-mel login utama dan kata laluan akaun sedia ada sebelum mengesahkan pautan ini. E-mel tambahan belum boleh digunakan sebagai login.\n\nPautan pengesahan: ".(string)($data['url']??'')."\nPautan tamat tempoh dalam 60 minit. Selepas pemilikan disahkan, identity approval Admin masih diperlukan. Jika bukan permintaan anda, abaikan mesej ini.";}if($r['template_key']==='activation'&&in_array($data['context']??null,['staff_invitation','approved_staff_invitation'],true)){$subject=($data['context']==='approved_staff_invitation'?'Permohonan Pendaftaran Diluluskan — ':'').'Jemputan Aktifkan Akaun Staf epejabat.net';$body="Cipta Kata Laluan Akaun Staf\n\nIdentiti dan organisasi anda telah disahkan pentadbir. Buka pautan di bawah untuk mencipta dan mengesahkan kata laluan sendiri. Tidak perlu login atau langkah pengesahan e-mel berasingan.\n\n".(string)($data['url']??'')."\n\nPautan sekali guna; tamat tempoh 60 minit selepas dijana. Tiada kata laluan dihantar melalui e-mel. Jika anda tidak menjangka jemputan ini, abaikan mesej.";}Smtp::send(self::config(),$r['email'],$subject,$body);Database::query($p,"UPDATE notification_deliveries SET status='SENT',sent_at=UTC_TIMESTAMP(),attempts=attempts+1,last_error=NULL,payload_cipher=? WHERE id=?",[Crypto::seal('{}'),$r['id']]);$result['sent']++;}catch(\Throwable $e){$attempt=(int)$r['attempts']+1;$expired=isset($data['expires_at'])&&strtotime($data['expires_at'].' UTC')<time();$status=$attempt>=5||$expired?'FAILED':'QUEUED';$ref=Support::log($e);Database::query($p,'UPDATE notification_deliveries SET status=?,attempts=?,next_attempt_at=DATE_ADD(UTC_TIMESTAMP(),INTERVAL ? SECOND),last_error=? WHERE id=?',[$status,$attempt,min(3600,60*(2**$attempt)),($e instanceof SmtpFailure?$e->safeDiagnostic():'Delivery unavailable').' ; ref '.$ref,$r['id']]);$result['failed']++;}unset($data);}}finally{Database::query($p,"SELECT RELEASE_LOCK(CONCAT('ep_mail_',LEFT(SHA2(DATABASE(),256),40)))");}return $result;
    }
}
